# 这 8 条的**实测覆盖率**（闸门算出来的值，钉住"为什么单靠覆盖率不够"）：
#   2355=1.000 / 2855=1.000 / 2863=1.000 / 2610=1.000（命中 融资+亿元）
#   1765=0.076 / 1794=0.076 / 2905=0.076 / 2930=0.076（只命中 亿元）
REAL_COVERAGE = {
    "article:2355": 1.0, "article:2855": 1.0, "article:2863": 1.0, "article:2610": 1.0,
    "article:1765": 0.0762, "article:1794": 0.0762, "article:2905": 0.0762, "article:2930": 0.0762,
}

# 需要的生效值回执字段（父任务口径：kept / dropped / floor / coverage_of_top1 / term_source）
REQUIRED_RECEIPT_KEYS = {
    "kept", "dropped", "floor", "keep_floor", "coverage_of_top1", "term_source",
    "weak", "gate", "reason", "terms", "reason_counts",
}


def _item(ref, title, content, *, score=10.0, method="keyword", source_type="article"):
    return {"evidence_ref": ref, "source_type": source_type, "title": title,
            "content_excerpt": content, "score": score, "retrieval_method": method,
            "metadata": {}}


class _EnvGuard(unittest.TestCase):
    """闸门相关 env 一律在本用例内自成一体，绝不污染别的测试。"""

    ENV_KEYS = ("QA_LEVEL1_RELEVANCE_GATE", "QA_LEVEL1_RELEVANCE_FLOOR",
                "QA_LEVEL1_RELEVANCE_KEEP", "QA_LEVEL1_AMOUNT_GATE",
                "QA_LEVEL1_MIN_DISTINCT_HITS", "QA_LEVEL1_SEMANTIC_STRONG")

    def setUp(self):
        self._saved = {key: os.environ.pop(key, None) for key in self.ENV_KEYS}

    def tearDown(self):
        for key, value in self._saved.items():
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = value


