class RealEightOfftopicTests(_EnvGuard):
    def test_fixture_is_the_real_eight_in_the_real_order(self):
        self.assertEqual([item["evidence_ref"] for item in REAL_EVIDENCE], [
            "article:2355", "article:1765", "article:2930", "article:2855",
            "article:2905", "article:2863", "article:1794", "article:2610"])
        self.assertEqual(8, len({item["evidence_ref"] for item in REAL_EVIDENCE}))
        # 真实命中说明（BM25 靠"億元/融资"词面撞上来的硬证据）
        self.assertIn("BM25", REAL_EVIDENCE[0]["match_reason"])
        self.assertIn("應天獲買家", REAL_EVIDENCE[1]["title"])

    def test_all_eight_are_offtopic_and_the_pack_goes_empty(self):
        """核心验收：**全部离题 → 证据 0 条**（允许返回空证据包）。"""
        kept, audit = qa_relevance.filter_offtopic_evidence(
            QUESTION, REAL_EVIDENCE, plan=PLAN)

        self.assertEqual([], kept, "8 条全部离题，证据包必须是空的")
        self.assertEqual(0, audit["kept"])
        self.assertEqual(8, audit["dropped"])
        self.assertEqual("level1_all_offtopic", audit["reason"])

    def test_receipt_carries_the_effective_values(self):
        kept, audit = qa_relevance.filter_offtopic_evidence(
            QUESTION, REAL_EVIDENCE, plan=PLAN)

        self.assertTrue(REQUIRED_RECEIPT_KEYS <= set(audit), sorted(REQUIRED_RECEIPT_KEYS - set(audit)))
        self.assertEqual(0.12, audit["floor"], "初始丢弃线（需实测校准）")
        self.assertEqual(0.20, audit["keep_floor"], "初始保留线（需实测校准）")
        self.assertEqual("plan", audit["term_source"])
        self.assertEqual(["亿元", "融资"], audit["terms"], "核心词由整句 query 用既有分词器拆出")
        self.assertEqual("applied", audit["amount_gate"])
        self.assertEqual([{"raw": "近3亿元", "value_yi": 3.0, "approximate": True}],
                         audit["amount_constraints"])
        # 覆盖率实测值：单靠覆盖率会留下 4 条离题的 → 闸门等于没开
        measured = {row["evidence_ref"]: round(row["coverage"], 3) for row in audit["excluded"]}
        self.assertEqual({"article:2355": 1.0, "article:2855": 1.0,
                          "article:2863": 1.0, "article:2610": 1.0,
                          "article:1765": 0.076, "article:1794": 0.076,
                          "article:2905": 0.076, "article:2930": 0.076}, measured)
        self.assertEqual(1.0, audit["coverage_of_top1"], "分数最高的那条（article:2610）覆盖率 1.0")
        self.assertEqual("article:2610", audit["top1_ref"])

    def test_both_mechanisms_are_named_in_the_receipt(self):
        """"为什么被砍"必须分类记账：4 条金额对不上、4 条只命中金额字面。"""
        _, audit = qa_relevance.filter_offtopic_evidence(QUESTION, REAL_EVIDENCE, plan=PLAN)

        self.assertEqual({"amount_constraint_miss": 4, "only_amount_literals": 4},
                         audit["reason_counts"])
        reasons = {row["evidence_ref"]: row["reason"] for row in audit["excluded"]}
        self.assertEqual("amount_constraint_miss", reasons["article:2355"])
        self.assertEqual("amount_constraint_miss", reasons["article:2610"])
        self.assertEqual("only_amount_literals", reasons["article:1765"],
                         "應天獲買家3億掃兩伙只命中“亿元”，是硬否决②")
        self.assertIn("金额与问题对不上 4 条", qa_relevance.offtopic_reason_text(audit["reason_counts"]))

    def test_input_evidence_objects_are_not_mutated(self):
        """标注只进 metadata，且不许改动调用方传进来的对象（证据层还要用它登记 rejected）。"""
        before = json.dumps(REAL_EVIDENCE, ensure_ascii=False, sort_keys=True)

        qa_relevance.filter_offtopic_evidence(QUESTION, REAL_EVIDENCE, plan=PLAN)

        self.assertEqual(before, json.dumps(REAL_EVIDENCE, ensure_ascii=False, sort_keys=True))


