class SecondaryRuleTests(_EnvGuard):
    """主判据不可用时（计划抽不出实词 → n-gram 兜底词）：**不许静默放行**，走次级判据。"""

    QUESTION = "量子计算芯片最近的商业化订单有哪些？"

    def _plan(self):
        return dict(PLAN, question=self.QUESTION, queries=[], entities=[], topics=[],
                    policy_anchors={})

    def test_no_plan_terms_still_gates_through_the_ngram_fallback(self):
        offtopic = [_item("article:1", "汽车芯片供应链季度观察", "车规级芯片供给改善，功率半导体价格回落。")]
        on_topic = [_item("article:2", "量子计算芯片商业化订单落地", "首批量子计算芯片订单完成签约。")]

        dropped, audit_drop = qa_relevance.filter_offtopic_evidence(
            self.QUESTION, offtopic, plan=self._plan())
        kept, audit_keep = qa_relevance.filter_offtopic_evidence(
            self.QUESTION, on_topic, plan=self._plan())

        self.assertEqual("ngram_fallback", audit_drop["term_source"])
        self.assertNotEqual("not_applicable", audit_drop["gate"],
                            "抽不出实词时**不许**整体放行（那会让闸门静默失效）")
        self.assertEqual([], dropped)
        self.assertEqual({"ngram_insufficient_hits": 1}, audit_drop["reason_counts"])
        self.assertEqual(1, len(kept), "题内证据（≥2 个不同核心词命中）必须保留")

    def test_semantic_and_bm25_scores_are_never_compared_on_one_threshold(self):
        """同一段文本、同一个分数：语义通道留住、BM25 通道丢弃——两条量纲不共用一个阈值。"""
        text = ("某公司发布算力新品", "新一代算力平台发布，芯片供给是关键词之一。")
        semantic = [_item("article:3", text[0], text[1], score=72.0, method="semantic")]
        bm25 = [_item("article:3", text[0], text[1], score=72.0, method="bm25")]

        kept_semantic, audit_semantic = qa_relevance.filter_offtopic_evidence(
            self.QUESTION, semantic, plan=self._plan())
        kept_bm25, audit_bm25 = qa_relevance.filter_offtopic_evidence(
            self.QUESTION, bm25, plan=self._plan())

        self.assertEqual(1, len(kept_semantic), "语义分 0.72 ≥ 0.60 → 次级判据放行")
        self.assertEqual([], kept_bm25, "BM25 的 72 分不是语义分，不许拿同一个阈值比")
        self.assertEqual({"ngram_insufficient_hits": 1}, audit_bm25["reason_counts"])


class ReverseGuardTests(_EnvGuard):
    def test_same_batch_with_a_question_that_is_about_one_of_them(self):
        """同一批真实证据 + 一个**真的与其中一条相关**的问题 → 那条必须留下。"""
        question = "信托业三分类收官观察讲了什么"
        plan = dict(PLAN, question=question, queries=[question])

        kept, audit = qa_relevance.filter_offtopic_evidence(question, REAL_EVIDENCE, plan=plan)

        refs = [item["evidence_ref"] for item in kept]
        self.assertIn("article:2355", refs, "信托业三分类那条对这个问题是相关的，不许砍")
        self.assertNotIn("article:1765", refs, "應天獲買家那条仍然离题")
        self.assertLess(audit["kept"], 8)

